import { createRouter } from '@tanstack/react-router';

import { routeTree } from './routeTree.gen';

/**
 * The router configuration. `routeTree.gen.ts` is generated by the TanStack
 * Start Vite plugin on the first dev/build run; it is committed so
 * `pnpm typecheck` works without a build.
 */
export function getRouter() {
  return createRouter({
    routeTree,
    scrollRestoration: true,
    defaultPreload: 'intent',
  });
}
